{{\n    config(\n        materialized='incremental',\n        unique_key='order_id',\n        incremental_strategy='merge',\n        merge_update_columns=['order_sk', 'customer_id', 'order_date', 'order_status', 'billing_address', 'state_name', 'shipping_address', 'shipping_cost', 'shipping_method', 'discount_amount', 'tax_amount', 'total_amount', 'created_at', 'updated_at']\n    )\n}}\n\nwith base as (\n\n    -- i have to reference the bronze table\n    select *\n    from {{ ref('bronze_orders') }}\n    \n    {% if is_incremental() %}\n        where updated_at > (select max(updated_at) from {{ this }})\n    {% endif %}\n\n),\n\nstate_extracted as (  \n    --it takes base and adds a state_name column extracted from billing_address.\n\n    select\n        *,\n        -- Extract the 2-letter state abbreviation before the ZIP code\n        regexp_substr(billing_address, ',\\\\s([A-Z]{2})\\\\s\\\\d{5}', 1, 1, 'e', 1) as state_name\n    from base\n\n),\n\nfinal as (\n\n    select\n     row_number() over (order by order_id) as order_sk,\n        order_id,\n        customer_id,\n        order_date,\n        order_status,\n        billing_address,\n\n        -- Derived state_name based on state_code\n        case state_name\n            when 'AL' then 'Alabama'\n            when 'AK' then 'Alaska'\n            when 'AZ' then 'Arizona'\n            when 'AR' then 'Arkansas'\n            when 'CA' then 'California'\n            when 'CO' then 'Colorado'\n            when 'CT' then 'Connecticut'\n            when 'DE' then 'Delaware'\n            when 'FL' then 'Florida'\n            when 'GA' then 'Georgia'\n            when 'HI' then 'Hawaii'\n            when 'ID' then 'Idaho'\n            when 'IL' then 'Illinois'\n            when 'IN' then 'Indiana'\n            when 'IA' then 'Iowa'\n            when 'KS' then 'Kansas'\n            when 'KY' then 'Kentucky'\n            when 'LA' then 'Louisiana'\n            when 'ME' then 'Maine'\n            when 'MD' then 'Maryland'\n            when 'MA' then 'Massachusetts'\n            when 'MI' then 'Michigan'\n            when 'MN' then 'Minnesota'\n            when 'MS' then 'Mississippi'\n            when 'MO' then 'Missouri'\n            when 'MT' then 'Montana'\n            when 'NE' then 'Nebraska'\n            when 'NV' then 'Nevada'\n            when 'NH' then 'New Hampshire'\n            when 'NJ' then 'New Jersey'\n            when 'NM' then 'New Mexico'\n            when 'NY' then 'New York'\n            when 'NC' then 'North Carolina'\n            when 'ND' then 'North Dakota'\n            when 'OH' then 'Ohio'\n            when 'OK' then 'Oklahoma'\n            when 'OR' then 'Oregon'\n            when 'PA' then 'Pennsylvania'\n            when 'RI' then 'Rhode Island'\n            when 'SC' then 'South Carolina'\n            when 'SD' then 'South Dakota'\n            when 'TN' then 'Tennessee'\n            when 'TX' then 'Texas'\n            when 'UT' then 'Utah'\n            when 'VT' then 'Vermont'\n            when 'VA' then 'Virginia'\n            when 'WA' then 'Washington'\n            when 'WV' then 'West Virginia'\n            when 'WI' then 'Wisconsin'\n            when 'WY' then 'Wyoming'\n            else null\n        end as state_name,\n\n        shipping_address,\n        shipping_cost,\n        shipping_method,\n        discount_amount,\n        tax_amount,\n        total_amount,\n        created_at,\n        updated_at\n\n    from state_extracted\n),\n\ncleaned_order as (\n\n        select\n            order_sk,\n            order_id,\n            customer_id,\n            cast(order_date as date) as order_date,\n            cast(created_at as timestamp) as created_at,\n            cast(updated_at as timestamp) as updated_at,\n\n            billing_address,\n            state_name,\n            shipping_address,\n\n            cast(discount_amount as numeric(10, 2)) as discount_amount,\n            cast(shipping_cost as numeric(10, 2)) as shipping_cost,\n            cast(tax_amount as numeric(10, 2)) as tax_amount,\n            cast(total_amount as numeric(10, 2)) as total_amount,\n\n            order_status,\n\n            -- 🛠 Replace NULL with 'Outsourced'\n            coalesce(shipping_method, 'Outsourced') as shipping_method\n\n        from final\n        where order_id is not null\n\n    )\n\nselect * from cleaned_order
